#include <stdio.h>

// Lỗi: vòng lặp dừng ở n - 1 nên bỏ mất số n. Sửa điều kiện thành i <= n.
int tong_1_den(int n) {
    int s = 0;
    for (int i = 1; i <= n; i++) s += i;
    return s;
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%d\n", tong_1_den(n));
    return 0;
}
